DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'invite_status') THEN
    CREATE TYPE "public"."invite_status" AS ENUM('pending', 'accepted', 'expired');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'member_role') THEN
    CREATE TYPE "public"."member_role" AS ENUM('owner', 'editor', 'viewer');
  END IF;
END $$;

CREATE TABLE IF NOT EXISTS "project_invites" (
  "id" serial PRIMARY KEY NOT NULL,
  "projectId" integer NOT NULL,
  "invitedByUserId" integer NOT NULL,
  "email" varchar(320) NOT NULL,
  "role" "member_role" DEFAULT 'editor' NOT NULL,
  "token" varchar(64) NOT NULL,
  "status" "invite_status" DEFAULT 'pending' NOT NULL,
  "createdAt" timestamp DEFAULT now() NOT NULL,
  "expiresAt" timestamp NOT NULL,
  CONSTRAINT "project_invites_token_unique" UNIQUE("token")
);

CREATE TABLE IF NOT EXISTS "project_members" (
  "id" serial PRIMARY KEY NOT NULL,
  "projectId" integer NOT NULL,
  "userId" integer NOT NULL,
  "role" "member_role" DEFAULT 'viewer' NOT NULL,
  "addedAt" timestamp DEFAULT now() NOT NULL
);

ALTER TABLE "project_invites" ADD CONSTRAINT "project_invites_projectId_projects_id_fk" FOREIGN KEY ("projectId") REFERENCES "public"."projects"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "project_invites" ADD CONSTRAINT "project_invites_invitedByUserId_users_id_fk" FOREIGN KEY ("invitedByUserId") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "project_members" ADD CONSTRAINT "project_members_projectId_projects_id_fk" FOREIGN KEY ("projectId") REFERENCES "public"."projects"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "project_members" ADD CONSTRAINT "project_members_userId_users_id_fk" FOREIGN KEY ("userId") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action;

CREATE INDEX IF NOT EXISTS "pi_projectId_idx" ON "project_invites" USING btree ("projectId");
CREATE INDEX IF NOT EXISTS "pi_email_idx" ON "project_invites" USING btree ("email");
CREATE INDEX IF NOT EXISTS "pi_token_idx" ON "project_invites" USING btree ("token");
CREATE INDEX IF NOT EXISTS "pm_projectId_idx" ON "project_members" USING btree ("projectId");
CREATE INDEX IF NOT EXISTS "pm_userId_idx" ON "project_members" USING btree ("userId");
CREATE INDEX IF NOT EXISTS "pm_project_user_idx" ON "project_members" USING btree ("projectId","userId");

